    @Override public void setupAnim(TechtainArkRenderState state){super.setupAnim(state);float time=state.actionSeconds;String clip=state.action;
        if(clip.equals("dash")){if(time<.7F){clip="dash_intro";time*=.6667F/.7F;}else if(time<state.dashEnd/20F){clip="dash_loop";time-=.7F;}else{clip="dash_end";time-=state.dashEnd/20F;}}
        else if(clip.equals("stun")){clip="unconscious";time=Math.min(time,4);}
        var definition=TechtainArkAnimations.ALL.getOrDefault(clip,TechtainArkAnimations.idle);
        if(!definition.looping()&&!clip.equals("dead")&&!clip.equals("unconscious")&&time>=definition.lengthInSeconds()){time-=definition.lengthInSeconds();clip="idle";}
        animations.getOrDefault(clip,animations.get("idle")).apply((long)(time*1000),1);
    }
